tems-length=\"serverItemsLength\"\n            :loading=\"loading\"\n            :sort-by.sync=\"sortBy\"\n            :sort-desc.sync=\"sortDesc\"\n            :footer-props=\"{\n                disableItemsPerPage: disableItemsPerPage,\n                disablePagination: disablePagination,\n                showFirstLastPage: true,\n                showCurrentPage: true,\n                itemsPerPageOptions: [10, 20, 50, 100]\n            }\"\n        >\n            <template v-slot:[`item.status`]=\"{ item }\">\n                {{ $t(`shippingstatus.${item.status}`) }}\n            </template>\n            <template v-slot:[`item.updated_at`]=\"{ item }\">\n                <div v-if=\"item.updated_at\">\n                    {{ item.updated_at | moment(\"dddd, Do MMMM YYYY\") }}\n                </div>\n            </template>\n            <template v-slot:[`item.status_actions`]=\"{ item }\">\n                <CButtonGroup>\n                    <CButton\n                        v-for=\"action in item.status_actions\"\n                        :key=\"action.key\"\n                        :color=\"action.color\"\n                        :disabled=\"action.disabled\"\n                        size=\"sm\"\n                        @click=\"click(item, action)\"\n                    >\n                        {{ action.title }}\n                    </CButton>\n                </CButtonGroup>\n            </template>\n            <template v-slot:[`item.actions`]=\"{ item }\">\n                <CButtonGroup>\n                    <CButton\n                        v-for=\"action in item.actions\"\n                        :key=\"action.key\"\n                        :color=\"action.color\"\n                        :disabled=\"action.disabled\"\n                        size=\"sm\"\n                        @click=\"click(item, action)\"\n                    >\n                        {{ action.title }}\n                    </CButton>\n                </CButtonGroup>\n            </template>\n        </v-data-table>\n    </div>\n</template>\n<script>\n//\nimport { Dialog } from \"@/components\";\n\nexport default {\n    name: \"ShippingTable\",\n    props: {\n        clientId: null\n    },\n    components: {\n        Dialog\n    },\n    data() {\n        return {\n            searchText: null,\n            page: 1,\n            serverItemsLength: 0,\n            pageCount: 0,\n            items: [],\n            loading: false,\n            options: {},\n            sortBy: \"client_name\",\n            sortDesc: false,\n            disableItemsPerPage: false,\n            disablePagination: false,\n            headers: [\n                {\n                    text: this.$t(\"number\"),\n                    value: \"generated_id\"\n                },\n                {\n                    text: `${this.$t(\"client\")}${this.$t(\"number\")}`,\n                    value: \"client_number\"\n                },\n                {\n                    text: `${this.$t(\"client\")}${this.$t(\"name\")}`,\n                    value: \"client_name\"\n                },\n                {\n                    text: `${this.$t(\"client\")}${this.$t(\"contact\")}`,\n                    value: \"client_contact\"\n                },\n                {\n                    text: `${this.$t(\"client\")}${this.$t(\"phone\")}`,\n                    value: \"formated_phone\",\n                    sortable: false\n                },\n                {\n                    text: `${this.$t(\"client\")}${this.$t(\"address\")}`,\n                    value: \"client_address\"\n                },\n                {\n                    text: `${this.$t(\"totalunit\")}`,\n                    value: \"total_unit\",\n                    sortable: false\n                },\n                {\n                    text: `${this.$t(\"subtotal\")}`,\n                    value: \"subtotal\",\n                    sortable: false\n                },\n                {\n                    text: `${this.$t(\"status\")}`,\n                    value: \"status\",\n                    sortable: false\n                },\n                { text: this.$t(\"updatedat\"), value: \"updated_at\" },\n                {\n                    text: `${this.$t(\"status\")}${this.$t(\"actions\")}`,\n                    value: \"status_actions\",\n                    sortable: false\n                },\n                { text: this.$t(\"actions\"), value: \"actions\", sortable: false }\n            ]\n        };\n    },\n    watch: {\n        options: {\n            handler() {\n                this.fetch();\n            }\n        },\n        loading() {\n            this.disableItemsPerPage = this.loading;\n            this.disablePagination = this.loading;\n        }\n    },\n    methods: {\n        fetch(reset = false) {\n            let self = this;\n            self.loading = true;\n            const { page, itemsPerPage, sortBy, sortDesc } = self.options;\n            let data = {\n                client_id: self.$props.clientId,\n                page: reset ? 1 : page,\n                per_page: itemsPerPage,\n                sort_by: sortBy,\n                sort_desc: sortDesc,\n                keyword: self.searchText\n            };\n            this.$store\n                .dispatch(\"goods/shipping/get\", data)\n                .then(response => {\n                    let res = JSON.parse(JSON.stringify(response.data));\n                    self.items = res.data;\n                    self.serverItemsLength = res.total;\n                    self.pageCount = res.last_page;\n                    self.page = res.current_page;\n                    self.loading = false;\n                })\n                .catch(error => {\n                    self.loading = false;\n                });\n        },\n        search() {\n            this.fetch(true);\n        },\n        download() {\n            let self = this;\n            self.loading = true;\n            const { itemsPerPage, sortBy, sortDesc } = self.options;\n            let data = {\n                client_id: self.$props.clientId,\n                per_page: itemsPerPage,\n                sort_by: sortBy,\n                sort_desc: sortDesc,\n                search: self.searchText,\n                extension: \"pdf\"\n            };\n            this.$store\n                .dispatch(\"goods/shipping/export\", data)\n                .then(response => {\n                    self.loading = false;\n                })\n                .catch(error => {\n                    self.loading = false;\n                });\n        },\n        reload() {\n            this.fetch();\n        },\n        async click(item, action) {\n            let type = action.type;\n            switch (type) {\n                case \"UpdateStatus\":\n                    if (\n                        await this.$refs.dialog.open(\n                            this.$t(\"alert.title\"),\n                            this.$t(\"alert.update\")\n                        )\n                    ) {\n                        let self = this;\n                        if (self.loading) {\n                            return;\n                        }\n                        self.loading = true;\n                        this.$store\n                            .dispatch(\"goods/shipping/update\", {\n                                id: item.id,\n                                status: action.status,\n                                type: \"UPDATE\"\n                            })\n                            .then(response => {\n                                self.loading = false;\n                                self.fetch();\n                            })\n                            .catch(error => {\n                                self.loading = false;\n                            });\n                    }\n                    break;\n                case \"RouterPush\":\n                    this.$router.push({\n                        name: \"ShippingDetails\",\n                        params: { id: item.id }\n                    });\n                    break;\n            }\n            // console.log(id, key);\n        }\n    }\n};\n</script>\n\n<style scoped>\n.v-select {\n    font-size: 1em;\n    font-weight: 100;\n}\n</style>\n"],"sourceRoot":""}]);
